import{_ as o,a}from"./chunks/crd-code.CuKzBF2I.js";import{_ as r,o as s,c as e,a5 as n}from"./chunks/framework.BYXPg_yw.js";const k=JSON.parse('{"title":"원격지원","description":"","frontmatter":{"layout":"doc","outline":"deep","title":"원격지원"},"headers":[],"relativePath":"ko/manual/support/remote.md","filePath":"ko/manual/support/remote.md","lastUpdated":1792139892000}'),i={name:"ko/manual/support/remote.md"};function l(h,t,d,g,p,c){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="원격지원-chrome-원격-데스크톱" tabindex="-1">원격지원 (Chrome 원격 데스크톱) <a class="header-anchor" href="#원격지원-chrome-원격-데스크톱" aria-label="Permalink to &quot;원격지원 (Chrome 원격 데스크톱)&quot;">​</a></h1><p>원격지원이 필요하면 <strong><a href="mailto:rbq.support@rainbow-robotics.com" target="_blank" rel="noreferrer">rbq.support@rainbow-robotics.com</a></strong> 으로 메일을 보내세요. 지원팀이 따로 연락해 일정을 잡습니다.</p><p>원격지원에서는 현장의 노트북 한 대를 <strong>Chrome 원격 데스크톱</strong>으로 지원팀에 열어 줍니다. 지원 엔지니어는 그 노트북을 거쳐 로봇을 점검합니다. <strong>노트북 준비 → 로봇에 연결 → 프로그램 설치 → 접속 코드 전달</strong> 순서로 진행하면 됩니다.</p><div class="danger custom-block"><p class="custom-block-title">⚠ 원격지원 중에는 로봇 옆에 사람이 있어야 합니다</p><p>원격으로 로봇 소프트웨어를 재시작하거나 로봇을 움직일 수 있습니다. 지원이 끝날 때까지 <strong>로봇 주변을 비우고</strong>, 한 사람이 로봇 옆에서 언제든 비상 정지할 수 있게 대기하세요. 절차는 <a href="/RBQ/nightly/ko/guides/common/emo.html">비상 정지 및 복구</a>를 보세요.</p></div><h2 id="what-you-need" tabindex="-1">1. 준비물 <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;1. 준비물 {#what-you-need}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td><strong>노트북</strong></td><td>Windows · macOS · Ubuntu, <strong>Chrome 브라우저</strong> 설치</td></tr><tr><td><strong>인터넷</strong></td><td>지원팀이 노트북에 접속하는 경로입니다</td></tr><tr><td><strong>로봇 네트워크</strong></td><td>로봇 Wi-Fi(<code>RBQ_</code> 로 시작하는 이름) 또는 스위치 허브에 꽂은 LAN 케이블</td></tr><tr><td><strong>Google 계정</strong></td><td>Chrome 원격 데스크톱 설치에 필요합니다</td></tr><tr><td><strong>현장 담당자</strong></td><td>노트북 앞과 로봇 옆을 지킬 사람. 지원팀과 통화할 수 있어야 합니다</td></tr></tbody></table><h2 id="connect-laptop" tabindex="-1">2. 노트북을 로봇과 인터넷에 함께 연결하기 <a class="header-anchor" href="#connect-laptop" aria-label="Permalink to &quot;2. 노트북을 로봇과 인터넷에 함께 연결하기 {#connect-laptop}&quot;">​</a></h2><p>노트북은 <strong>로봇 네트워크와 인터넷에 동시에</strong> 연결되어 있어야 합니다. 둘 중 하나만 되면 지원팀이 노트북에 들어와도 로봇에 닿지 못합니다.</p><table tabindex="0"><thead><tr><th>로봇 구성</th><th>연결 방법</th></tr></thead><tbody><tr><td><strong>LTE/5G 모듈이 있음</strong></td><td>로봇 Wi-Fi 하나로 둘 다 됩니다</td></tr><tr><td><strong>LTE/5G 모듈이 없음</strong></td><td>로봇 스위치 허브에 <strong>LAN 케이블</strong>을 꽂고, 인터넷은 <strong>다른 Wi-Fi</strong> 나 휴대폰 핫스팟으로 잡습니다</td></tr></tbody></table><p>연결한 뒤 노트북에서 로봇 모션 PC 까지 닿는지 확인합니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows 는 명령 프롬프트, macOS 는 터미널에서</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.0.10</span></span></code></pre></div><p>응답이 오면 됩니다. 응답이 없으면 <a href="/RBQ/nightly/ko/manual/interface/network.html">네트워크 구성도</a>에서 로봇의 구성을 확인하고, 노트북 주소가 <code>192.168.0.x</code> 대역인지 보세요.</p><div class="warning custom-block"><p class="custom-block-title">⚠ 노트북이 잠들지 않게 하세요</p><p>절전·화면 잠금으로 들어가면 원격 연결이 끊깁니다. 지원 동안은 <strong>전원을 연결하고</strong>, 절전 모드를 끄고, 덮개를 닫지 마세요.</p></div><h2 id="install" tabindex="-1">3. Chrome 원격 데스크톱 설치하기 <a class="header-anchor" href="#install" aria-label="Permalink to &quot;3. Chrome 원격 데스크톱 설치하기 {#install}&quot;">​</a></h2><ol><li>노트북의 Chrome 에서 <strong><a href="https://remotedesktop.google.com/support" target="_blank" rel="noreferrer">remotedesktop.google.com/support</a></strong> 를 엽니다.</li><li>Google 계정으로 로그인합니다.</li><li>오른쪽 아래에 <strong>Chrome 원격 데스크톱을 설치하시겠습니까?</strong> 창이 뜨면 <strong>설치</strong> 를 누릅니다.</li><li><strong>이 기기</strong> 아래 <strong>화면 공유</strong> 카드의 다운로드 버튼을 누르고, 안내에 따라 확장 프로그램과 설치 파일을 설치합니다.</li><li>설치가 끝나면 같은 카드에 <strong>코드 생성</strong> 버튼이 나타납니다.</li></ol><figure><img src="`+o+`" alt="Chrome 원격 데스크톱 — 화면 공유 카드와 오른쪽 아래 설치 창"><figcaption style="text-align:center;">[ 오른쪽 아래 설치 창에서 설치 → 화면 공유 카드의 다운로드 버튼 ]</figcaption></figure><p>설치는 한 번만 하면 됩니다. 다음 원격지원부터는 5번부터 시작합니다.</p><h3 id="install-ubuntu" tabindex="-1">Ubuntu 노트북에서 설치하기 <a class="header-anchor" href="#install-ubuntu" aria-label="Permalink to &quot;Ubuntu 노트북에서 설치하기 {#install-ubuntu}&quot;">​</a></h3><p>Ubuntu 에서는 4번의 다운로드 버튼을 누르면 <code>.deb</code> 파일이 받아집니다. 이 파일은 터미널에서 설치합니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Downloads</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./chrome-remote-desktop_current_amd64.deb</span></span></code></pre></div><p>설치가 끝나면 Chrome 페이지를 <strong>새로고침</strong>합니다. <strong>화면 공유</strong> 카드에 <strong>코드 생성</strong> 버튼이 보이면 설치된 것입니다. 자세한 내용은 Google 공식 안내의 <strong>Linux에서 Chrome 원격 데스크톱 사용</strong> 항목을 보세요 (<a href="https://support.google.com/chrome/answer/1649523?hl=ko" target="_blank" rel="noreferrer">Chrome 원격 데스크톱 도움말</a>).</p><h2 id="share-code" tabindex="-1">4. 접속 코드 전달하기 <a class="header-anchor" href="#share-code" aria-label="Permalink to &quot;4. 접속 코드 전달하기 {#share-code}&quot;">​</a></h2><ol><li><p>지원팀과 <strong>통화가 연결된 상태에서</strong> <strong>코드 생성</strong> 을 누릅니다.</p></li><li><p>화면에 나온 <strong>12자리 숫자</strong>를 지원팀에 불러 줍니다.</p><figure><img src="`+a+'" alt="Chrome 원격 데스크톱 — 화면 공유 카드에 나온 12자리 액세스 코드"><figcaption style="text-align:center;">[ 12자리 액세스 코드와 남은 시간 ]</figcaption></figure></li><li><p>지원팀이 접속을 요청하면 노트북에 확인 창이 뜹니다. 상대 이메일을 확인하고 <strong>공유</strong> 를 누릅니다.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">📝 코드는 5분 동안만 유효합니다</p><p>시간이 지나면 코드가 사라집니다. 지원팀이 받을 준비가 된 뒤에 만들고, 만료됐으면 다시 <strong>코드 생성</strong> 을 누르세요. 코드는 한 번 쓰면 다시 쓸 수 없습니다.</p></div><h2 id="during" tabindex="-1">5. 원격지원 중에 <a class="header-anchor" href="#during" aria-label="Permalink to &quot;5. 원격지원 중에 {#during}&quot;">​</a></h2><ul><li><strong>노트북의 마우스·키보드를 만지지 마세요.</strong> 지원 엔지니어와 동시에 조작하면 명령이 섞입니다.</li><li><strong>앱으로 로봇을 조종하지 마세요.</strong> 지원팀이 요청할 때만 조작합니다.</li><li><strong>30분마다</strong> 노트북에 <strong>공유를 계속할지 묻는 창</strong>이 뜹니다. 지원팀이 계속 작업 중이면 계속을 눌러 주세요. 응답하지 않으면 연결이 끊깁니다.</li><li>지원팀이 로봇을 앉히거나 재시작하겠다고 하면, 로봇 주변에 사람이 없는지 확인한 뒤 알려 주세요.</li></ul><h2 id="finish" tabindex="-1">6. 끝내기 <a class="header-anchor" href="#finish" aria-label="Permalink to &quot;6. 끝내기 {#finish}&quot;">​</a></h2><ol><li>지원팀이 끝났다고 알리면 노트북 화면의 <strong>공유 중지</strong> 를 누릅니다.</li><li>지원팀이 안내한 대로 로봇을 다시 기동해 정상 동작하는지 확인합니다.</li></ol><p>공유를 멈추면 지원팀은 더 이상 노트북에 들어올 수 없습니다. 다음에는 새 코드가 필요합니다.</p><h2 id="see-also" tabindex="-1">함께 보면 좋은 곳 <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;함께 보면 좋은 곳 {#see-also}&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/ko/manual/support/">기술지원 요청</a> — 원격지원 전에 증상과 로그를 먼저 접수합니다</li><li><a href="https://support.google.com/chrome/answer/1649523?hl=ko" target="_blank" rel="noreferrer">Chrome 원격 데스크톱 도움말</a> — Google 공식 안내 (설치 · 화면 공유 · Linux)</li><li><a href="/RBQ/nightly/ko/manual/interface/network.html">네트워크 구성도</a> — 로봇의 주소와 연결 구성</li><li><a href="/RBQ/nightly/ko/guides/common/emo.html">비상 정지 및 복구</a></li></ul>',31)])])}const b=r(i,[["render",l]]);export{k as __pageData,b as default};
